contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint fundAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fundAmount, "insufficient test balance");
        c.sendMoney(address(this), fundAmount); if (__ESBMC_reverted()) return;

        uint balanceBefore = address(c).balance;

        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(withdrawAmount <= balanceBefore ? (!reverted && address(c).balance == balanceBefore - withdrawAmount) : reverted);
    }

    receive() external payable {}
}

