pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 fundAmount, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        try c.sendMoney(address(this), fundAmount) {} catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(withdrawAmount <= balanceBefore ? (!reverted && address(c).balance == balanceBefore - withdrawAmount) : reverted);
    }

    function testFuzz_run(uint256 fundAmount, uint256 withdrawAmount) public {
        _run(fundAmount, withdrawAmount);
    }

    receive() external payable {}
}
